  quoted_cache_dir=$(printf %q "$PREFIX_CACHE_DIR")
  ssh -o BatchMode=yes "$PEER" "mkdir -p $quoted_cache_dir"
  if [[ $PREFIX_CACHE_BYTES == auto ]]; then
    local_free=$(cache_free_bytes "$PREFIX_CACHE_DIR")
