        const float av = a < 16 ? sv[lhs + a] : -INFINITY;
        const float bv = b < 16 ? sv[rhs + b] : -INFINITY;
        const int ai = a < 16 ? si[lhs + a] : -1;
        const int bi = b < 16 ? si[rhs + b] : -1;
