        mv[j] = take_a ? av : bv;
        mi[j] = take_a ? ai : bi;
        a += take_a;
        b += !take_a;
      }
      for (int j = 0; j < 16; ++j) { sv[lhs + j] = mv[j]; si[lhs + j] = mi[j]; }
    }
