  for (int l = 0; l < z.w.cfg.num_layers; ++l) {
    const std::size_t ao = (static_cast<std::size_t>(l) * z.max_batch + a) *
                               z.max_tokens * KV + static_cast<std::size_t>(start) * KV;
    const std::size_t bo = (static_cast<std::size_t>(l) * z.max_batch + b) *
