                                   std::uint64_t offset) {
  if ((reinterpret_cast<std::uintptr_t>(data) | bytes | offset) % kPrefixIoAlignment)
    fail("unaligned direct write");
  io_all(fd, const_cast<void*>(data), bytes, offset, true);
}

